55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	};
64	
65	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
66	
67	const quote = (step: QuoteStep): QuoteResult => {
68	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
69	  const premiumBeforeRounding =
70	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
71	  return { premium: Math.ceil(premiumBeforeRounding) };
72	};
73	
74	export const runScenario = (scenario: Scenario): ScenarioOutput => {
75	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
76	};
